using System; using System.Collections.Generic; using System.Linq;
using System.Text.Json; using System.Threading; using System.Threading.Tasks;
using Parcs.Agent.Runtime;

public class SubInt : IAgentComputation
{
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double a = 8.0 * input.WorkerIndex / 2.0;
        double b = 8.0 * (input.WorkerIndex + 1) / 2.0;
        int n = 10000;
        double h = (b - a) / n;
        double F(double x) => Math.Exp(-x / 4.0) * Math.Cos(x + 0.5 * Math.Sin(2 * x));
        double s = F(a) + F(b);
        for (int i = 1; i < n; i++)
        {
            double x = a + i * h;
            s += (i % 2 == 1 ? 4.0 : 2.0) * F(x);
        }
        s *= h / 3.0;
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { k = input.WorkerIndex, value = s })));
    }
}

public class Reduce : IAgentComputation
{
    public class Part { public int k { get; set; } public double value { get; set; } }
    public Task<AgentLayerResult> ExecuteAsync(AgentLayerInput input, CancellationToken ct)
    {
        double total = 0;
        int count = 0;
        for (int j = 0; j < 2; j++)
        {
            var outs = input.GetPreviousOutputs(j);
            foreach (var o in outs)
            {
                if (o == null) continue;
                var p = JsonSerializer.Deserialize<Part>(o);
                total += p.value;
                count++;
            }
        }
        return Task.FromResult(AgentLayerResult.Ok(JsonSerializer.Serialize(new { I = total, parts = count })));
    }
}

